def transform(grid):
    # Reconstruct masked portions by the matching point reflected across the horizontal midline.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                out[r][c] = grid[h-1-r][c]
    return out

